mkdir -p /tmp/pw/check && cat > /tmp/pw/check/check.mjs <<'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 800, height: 700 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
page.on('requestfailed', (r) => errors.push(`[requestfailed] ${r.url()}`));

await page.goto('http://localhost:5174/', { waitUntil: 'networkidle' });

const report = {};
report.h1 = await page.textContent('h1');
report.labels = await page.$$eval('label', (els) => els.map((e) => ({ text: e.textContent.trim(), htmlFor: e.htmlFor })));
report.inputs = await page.$$eval('input', (els) => els.map((e) => ({ id: e.id, name: e.name, type: e.type, required: e.required, autocomplete: e.autocomplete })));
report.checkboxText = await page.$eval('form', (f) => f.textContent.includes('Запомнить меня'));
report.submitText = await page.$eval('button[type="submit"]', (b) => b.textContent.trim());
report.bodyClass = await page.$eval('body', (b) => b.className);
report.cardBox = await page.$eval('.login-card', (c) => { const r = c.getBoundingClientRect(); return { w: r.width, h: r.height }; });
report.fontFamily = await page.$eval('body', (b) => getComputedStyle(b).fontFamily);

// Interactions
await page.fill('#login-email', 'user@example.com');
await page.fill('#login-password', 'secret123');
await page.click('text=Запомнить меня');
report.checkboxChecked = await page.$eval('input[type="checkbox"]', (c) => c.checked);
report.emailValue = await page.inputValue('#login-email');
report.passwordValue = await page.inputValue('#login-password');

// Clicking label focuses the input (htmlFor wiring)
await page.click('label[for="login-email"]');
report.focusedAfterLabelClick = await page.evaluate(() => document.activeElement?.id);

// Submit with empty required fields -> native validation should block
await page.fill('#login-email', '');
await page.fill('#login-password', '');
await page.click('button[type="submit"]');
report.emailValidity = await page.$eval('#login-email', (e) => e.validationMessage);

await page.screenshot({ path: '/tmp/pw/check/login.png', fullPage: true });

console.log(JSON.stringify(report, null, 2));
console.log('ERRORS:', JSON.stringify(errors, null, 2));
await browser.close();
EOF
cd /tmp/pw && timeout 120000 node check/check.mjs

mkdir -p /tmp/ssr && cd /tmp/ssr && ln -sfn /home/sandbox/workspace/node_modules node_modules && cat > /tmp/ssr/render.tsx <<'EOF'
import { renderToStaticMarkup } from 'react-dom/server';
import { App } from '/home/sandbox/workspace/src/App';

const html = renderToStaticMarkup(<App />);
console.log(html.replace(/></g, '>\n<'));
EOF
cd /home/sandbox/workspace && timeout 120 npx vite-node --root /home/sandbox/workspace /tmp/ssr/render.tsx > /tmp/ssr/out.html 2>/tmp/ssr/err.log; echo "exit=$?"; tail -5 /tmp/ssr/err.log | cut -c1-300; wc -l /tmp/ssr/out.html; grep -n "<label\|<input\|<button\|<h1\|checkbox" /tmp/ssr/out.html | cut -c1-220 | head -30

cd /tmp/ssr && cat > /tmp/ssr/ssr.mjs <<'EOF'
import { createServer } from 'vite';

const server = await createServer({
  root: '/home/sandbox/workspace',
  configFile: '/home/sandbox/workspace/vite.config.ts',
  server: { middlewareMode: true, hmr: false },
  appType: 'custom',
  logLevel: 'error',
  ssr: { noExternal: true },
});
try {
  const React = await server.ssrLoadModule('react');
  const { renderToStaticMarkup } = await server.ssrLoadModule('react-dom/server');
  const { App } = await server.ssrLoadModule('/src/App.tsx');
  const html = renderToStaticMarkup(React.createElement(App));
  console.log(html.replace(/></g, '>\n<'));
} catch (e) {
  console.error('SSR FAILED:', e && e.stack ? e.stack.slice(0, 2000) : e);
  process.exitCode = 1;
} finally {
  await server.close();
}
EOF
cd /tmp/ssr && timeout 170 node ssr.mjs > /tmp/ssr/out.html 2>/tmp/ssr/err2.log; echo "exit=$?"; grep -v "npm warn" /tmp/ssr/err2.log | head -20 | cut -c1-300; wc -l /tmp/ssr/out.html; grep -n "<label\|<input\|<button\|<h1\|Запомнить" /tmp/ssr/out.html | cut -c1-200 | head -30
